import Foundation

public enum Engine: String, CaseIterable, Sendable {
  case parakeet
  case whisper

  public var name: String {
    switch self {
    case .parakeet: "Parakeet"
    case .whisper: "Whisper"
    }
  }

  public var models: [ModelID] { ModelID.allCases.filter { $0.engine == self } }
}

/// One file of a model, pinned to the bytes the manifest script saw on Hugging Face.
struct ModelFile: Sendable, Hashable {
  let path: String
  let size: Int64
  let sha256: String
}

/// Every file a model needs, at one Hugging Face commit. Generated by
/// `scripts/models/pin-manifests.py` into ModelManifests.swift.
public struct ModelManifest: Sendable {
  let repository: String
  let revision: String
  /// Prepended to each file's path on disk. Parakeet keeps the folder FluidAudio loads from.
  let localPrefix: String
  let files: [ModelFile]

  public var totalBytes: Int64 { files.reduce(0) { $0 + $1.size } }

  func remoteURL(for file: ModelFile) -> URL {
    guard let base = URL(string: "https://huggingface.co/\(repository)/resolve/\(revision)/") else {
      preconditionFailure("The manifest for \(repository) has an invalid repository name")
    }
    return base.appending(path: file.path)
  }

  func localPath(for file: ModelFile) -> String { localPrefix + file.path }
}

/// The models a user can install. The raw value is the stored active-model preference and names
/// the install path, so changing one makes an installed copy unknown.
public enum ModelID: String, CaseIterable, Sendable, Identifiable {
  case parakeetV3 = "parakeet-tdt-0.6b-v3-coreml"
  case parakeetUltra = "parakeet-ultra-coreml"
  case whisperTurbo = "large-v3-turbo"

  public static let preferred = ModelID.parakeetV3

  public var id: Self { self }

  public var engine: Engine {
    switch self {
    case .parakeetV3, .parakeetUltra: .parakeet
    case .whisperTurbo: .whisper
    }
  }

  public var name: String {
    switch self {
    case .parakeetV3: "Parakeet v3"
    case .parakeetUltra: "Parakeet Ultra"
    case .whisperTurbo: "Whisper Turbo"
    }
  }

  public var summary: String {
    switch self {
    case .parakeetV3:
      "NVIDIA's multilingual model. Detects the language on its own and adds punctuation and capitals."
    case .parakeetUltra:
      "Moondream's retraining of Parakeet v3. Same 25 languages, with fewer mistakes."
    case .whisperTurbo:
      "OpenAI's Whisper large-v3, pruned for speed. Much faster, with a minor drop in quality."
    }
  }

  public var manifest: ModelManifest {
    switch self {
    case .parakeetV3: .parakeetV3
    case .parakeetUltra: .parakeetUltra
    case .whisperTurbo: .whisperTurbo
    }
  }

  /// Where the model lives under the local-models folder: a folder per Parakeet model, a
  /// `ggml-*.bin` file per Whisper model.
  var installPath: String {
    switch engine {
    case .parakeet: "\(engine.rawValue)/\(rawValue)"
    case .whisper: "whisper/ggml-\(rawValue).bin"
    }
  }

  /// Whisper is one file, installed by moving that file. The others install as a folder.
  var isSingleFile: Bool { engine == .whisper }
}
